import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const r="/assets/blocks-for-ha/grid/fr/light.png",n="/assets/blocks-for-ha/grid/fr/dark.png",l="/assets/blocks-for-ha/themes/fr/dark.png",i="/assets/blocks-for-ha/themes/fr/tritanopia.png",f=JSON.parse('{"title":"Thèmes et zoom","description":"","frontmatter":{"title":"Thèmes et zoom"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/themes.md","filePath":"fr/projects/blocks-for-ha/themes.md","lastUpdated":1792783045000}'),p={name:"fr/projects/blocks-for-ha/themes.md"};function d(c,e,u,m,h,b){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="themes-et-zoom" tabindex="-1">Thèmes et zoom <a class="header-anchor" href="#themes-et-zoom" aria-label="Permalink to &quot;Thèmes et zoom&quot;">​</a></h1><h2 id="logique-et-objets-depuis-0-1-56" tabindex="-1">Logique et Objets depuis 0.1.56 <a class="header-anchor" href="#logique-et-objets-depuis-0-1-56" aria-label="Permalink to &quot;Logique et Objets depuis 0.1.56&quot;">​</a></h2><p>Dans Standard/Dark, les blocs logiques sont bleus et les objets bruns, avec des libellés blancs lisibles. Modern et Tritanopia conservent leurs propres palettes. <strong>Si / sinon si / sinon</strong> est désormais disponible dans <strong>Logique</strong> : l’engrenage ouvre le constructeur de branches ; les branches sinon si et Sinon peuvent y être ajoutées ou retirées. Les conditions et séquences d’actions produisent une branche native HA. Les projets existants restent compatibles.</p><h2 id="grille-de-points-depuis-0-1-51" tabindex="-1">Grille de points depuis 0.1.51 <a class="header-anchor" href="#grille-de-points-depuis-0-1-51" aria-label="Permalink to &quot;Grille de points depuis 0.1.51&quot;">​</a></h2><p>L’espace de travail affiche une grille native Blockly bien visible, avec un espacement de 25 unités et l’alignement automatique, inspirée de <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/BlocklyEditor.tsx" target="_blank" rel="noreferrer">l’éditeur Blockly d’ioBroker</a>. Le fond et les points suivent immédiatement l’apparence <strong>Clair / Sombre / Système</strong>, y compris les changements du système. La palette Blockly détermine toujours les couleurs des blocs et des menus ; le fond suit l’application même avec la palette Dark.</p><p>Le zoom et le déplacement font suivre la grille. Ajuster ne modifie pas la taille des blocs du menu. L’apparence et la palette ne changent ni l’automatisation ni le YAML.</p><p><img src="'+r+'" alt="Grille claire"></p><p><img src="'+n+'" alt="Grille sombre"></p><p>Depuis <strong>0.1.27</strong>, les blocs UGSo Standard/Dark utilisent des libellés blancs. Les fonds bleus et bruns intermédiaires sont légèrement assombris pour un contraste d’au moins <strong>4,5:1</strong>. Les couleurs claires originales de Modern/Tritanopia utilisent une écriture sombre suffisamment contrastée. Les champs éditables restent distincts et lisibles. Les images DE/EN/FR du catalogue ont été régénérées avec cette correction.</p><p>Le thème de l’application et la palette Blockly sont <strong>indépendants</strong>. La langue des blocs est également un réglage distinct. Ni thèmes ni zoom ni langue ne modifient le YAML.</p><h2 id="palette-blockly" tabindex="-1">Palette Blockly <a class="header-anchor" href="#palette-blockly" aria-label="Permalink to &quot;Palette Blockly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Choix</th><th>Apparence</th><th>Source originale</th></tr></thead><tbody><tr><td>UGSo Standard</td><td>Couleurs des groupes UGSo, menu sombre et panneau de blocs clair</td><td>Adaptation UGSo de Blockly Classic</td></tr><tr><td>Dark</td><td>Espace de travail et panneau sombres, fond du menu distinct</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-dark" target="_blank" rel="noreferrer">theme-dark</a></td></tr><tr><td>Modern</td><td>Palette Modern originale avec bordures marquées et groupes UGSo</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-modern" target="_blank" rel="noreferrer">theme-modern</a></td></tr><tr><td>Tritanopia</td><td>Palette des groupes standard adaptée, complétée pour les groupes HA</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-tritanopia" target="_blank" rel="noreferrer">theme-tritanopia</a></td></tr></tbody></table><p>Tritanopia vise les personnes présentant cette déficience de vision des couleurs. Les blocs clairs ont des libellés sombres, les blocs sombres des libellés clairs. Les champs éditables restent visuellement distincts. Les noms des catégories apportent un repère supplémentaire. Cela ne constitue pas une certification complète d’accessibilité.</p><p><img src="'+l+'" alt="Palette Dark, blocs français"></p><p><img src="'+i+'" alt="Palette Tritanopia, blocs français"></p><p>Le choix est sauvegardé localement. Une préférence inconnue revient au standard ; si le stockage est bloqué, le changement reste possible pour la page actuelle.</p><h2 id="zoom" tabindex="-1">Zoom <a class="header-anchor" href="#zoom" aria-label="Permalink to &quot;Zoom&quot;">​</a></h2><p>Depuis <strong>0.1.40</strong>, tous les thèmes utilisent une <strong>police de 16 px</strong>. Le menu de blocs reste à <strong>100 %</strong> : ajustement, molette et zoom modifient uniquement l’espace de travail. Zoom initial 100 %, ajustement 85–120 %, zoom manuel 50–240 %. Les grandes automatisations restent défilables ; l’ajustement ne descend pas sous 85 % afin de préserver la lisibilité. Vérifié en Full HD, 2560 px et HiDPI.</p><h2 id="apparence-de-l-application" tabindex="-1">Apparence de l’application <a class="header-anchor" href="#apparence-de-l-application" aria-label="Permalink to &quot;Apparence de l’application&quot;">​</a></h2><p><strong>Darstellung</strong> propose <strong>Hell</strong>, <strong>Dunkel</strong> et <strong>System</strong> pour l’en-tête, les panneaux, formulaires, YAML, dialogues et éditeurs. System suit immédiatement la préférence de couleur du navigateur/système ; un choix manuel la remplace. Préférence locale, indépendante de la palette Blockly. Le badge Built with Blockly utilise automatiquement la variante adaptée.</p><p>Blockly et les plugins de thèmes/zoom sont épinglés à 13.3.0 et intégrés localement sous Apache-2.0. <a href="./blocks">Catalogue et liens des plugins</a>.</p>',21)])])}const k=t(p,[["render",d]]);export{f as __pageData,k as default};
